const q = (s) => s.replace(/'/g, "\\'");

// [animalId, da, nl, fr, es, da_desc, nl_desc, fr_desc, es_desc]
const animals = [
  // ===== BIOME 700: EIS =====
  [701, 'Isbjørn', 'IJsbeer', 'Ours polaire', 'Oso polar',
   'Isbjørnen er verdens største landrovdyr og er perfekt tilpasset til det arktiske miljø med sit tykke hvide pelseje og fede underlag. Den er en fremragende svømmer og jager primært sæler.',
   'De ijsbeer is het grootste landroofdier ter wereld en is perfect aangepast aan het arctische milieu met zijn dikke witte vacht en vetlaag. Het is een uitstekende zwemmer en jaagt voornamelijk op zeehonden.',
   'L\'ours polaire est le plus grand prédateur terrestre du monde et est parfaitement adapté à l\'environnement arctique avec sa fourrure blanche épaisse et sa couche de graisse. C\'est un excellent nageur qui chasse principalement les phoques.',
   'El oso polar es el mayor depredador terrestre del mundo y está perfectamente adaptado al entorno ártico con su grueso pelaje blanco y capa de grasa. Es un excelente nadador que caza principalmente focas.'],
  [702, 'Valsros', 'Walrus', 'Morse', 'Morsa',
   'Hvalrossen er let genkendelig på sine lange stødbånd, der kan blive over en meter lange. De er sociale dyr og lever i store kolonier på arktiske strande og isflager. Stødbåndene bruges til at hive sig op på is.',
   'Het walrus is gemakkelijk herkenbaar aan zijn lange slagtanden, die meer dan een meter lang kunnen worden. Het zijn sociale dieren die in grote kolonies leven op arctische stranden en ijsschollen. De slagtanden worden gebruikt om zichzelf op het ijs te trekken.',
   'Le morse est facilement reconnaissable à ses longues défenses, qui peuvent dépasser un mètre de longueur. Ce sont des animaux sociaux qui vivent en grandes colonies sur les plages et les floes arctiques. Les défenses sont utilisées pour se hisser sur la glace.',
   'La morsa es fácilmente reconocible por sus largos colmillos, que pueden superar el metro de longitud. Son animales sociales que viven en grandes colonias en playas árticas y témpanos de hielo. Los colmillos se usan para subirse al hielo.'],
  [703, 'Sæl', 'Zeehond', 'Phoque', 'Foca',
   'Sæler er exceptionelt tilpasset til livet i kolde have. Under vand er de hurtige og graciøse svømmere, men på land er de klodsede. De er vigtige byttedyr for isbjørne og orcaer.',
   'Zeehonden zijn uitzonderlijk aangepast aan het leven in koude zeeën. Onder water zijn ze snelle en gracieuze zwemmers, maar op het land zijn ze onhandig. Ze zijn belangrijk prooidier voor ijsberen en orka\'s.',
   'Les phoques sont exceptionnellement adaptés à la vie dans les mers froides. Sous l\'eau, ce sont des nageurs rapides et gracieux, mais sur terre, ils sont maladroits. Ils constituent un gibier important pour les ours polaires et les orques.',
   'Las focas están excepcionalmente adaptadas a la vida en mares fríos. Bajo el agua son nadadoras rápidas y gráciles, pero en tierra son torpes. Son presas importantes para osos polares y orcas.'],
  [704, 'Pingvin', 'Pinguïn', 'Manchot', 'Pingüino',
   'Pingviner er fugle, der ikke kan flyve, men er exceptionelt gode svømmere. De tilbringer størstedelen af deres liv i havet og kan dykke til dybder på over 500 meter. De lever i store kolonier.',
   'Pinguïns zijn vogels die niet kunnen vliegen, maar uitzonderlijk goede zwemmers zijn. Ze brengen het grootste deel van hun leven in de zee door en kunnen duiken tot diepten van meer dan 500 meter. Ze leven in grote kolonies.',
   'Les manchots sont des oiseaux qui ne peuvent pas voler mais sont exceptionnellement bons nageurs. Ils passent la majeure partie de leur vie en mer et peuvent plonger à des profondeurs de plus de 500 mètres. Ils vivent en grandes colonies.',
   'Los pingüinos son aves que no pueden volar pero son nadadores excepcionalmente buenos. Pasan la mayor parte de su vida en el mar y pueden bucear a profundidades de más de 500 metros. Viven en grandes colonias.'],
  [705, 'Kejserpingvin', 'Keizerspinguïn', 'Manchot empereur', 'Pingüino emperador',
   'Kejserpingvinen er den største pingvinart og lever i Antarktis. Under den kolde antarktiske vinter ruger hannerne på de æg, som hunnerne har lagt, og balancerer dem på fødderne for at holde dem varme.',
   'De keizerspinguïn is de grootste pinguïnsoort en leeft in Antarctica. Tijdens de koude Antarctische winter broeden de mannetjes op de eieren die de vrouwtjes hebben gelegd, en balanceren ze op hun voeten om ze warm te houden.',
   'Le manchot empereur est la plus grande espèce de manchot et vit en Antarctique. Pendant le froid hiver antarctique, les mâles couvent les œufs pondus par les femelles, les équilibrant sur leurs pattes pour les tenir chauds.',
   'El pingüino emperador es la especie de pingüino más grande y vive en la Antártida. Durante el frío invierno antártico, los machos incuban los huevos puestos por las hembras, equilibrándolos en sus patas para mantenerlos calientes.'],
  [706, 'Sneugle', 'Sneeuwuil', 'Harfang des neiges', 'Búho nival',
   'Sneuglens hvide fjerdragt giver fremragende camouflage i det snedækkede arktiske landskab. I modsætning til de fleste ugler er den aktiv om dagen. Den jager primært lemminger.',
   'Het witte verenkleed van de sneeuwuil biedt uitstekende camouflage in het besneeuwde arctische landschap. In tegenstelling tot de meeste uilen is het overdag actief. Het jaagt voornamelijk op lemmingen.',
   'Le plumage blanc du harfang des neiges offre un excellent camouflage dans le paysage arctique enneigé. Contrairement à la plupart des hiboux, il est actif pendant la journée. Il chasse principalement les lemmings.',
   'El plumaje blanco del búho nival proporciona un excelente camuflaje en el paisaje ártico cubierto de nieve. A diferencia de la mayoría de los búhos, es activo durante el día. Caza principalmente leminos.'],
  [707, 'Polarræv', 'Poolvos', 'Renard arctique', 'Zorro ártico',
   'Polarræven er en mester til at overleve i ekstreme arktiske forhold. Dens tykke pelaje skifter farve fra hvid om vinteren til brun eller grå om sommeren. Den kan modstå temperaturer ned til -70°C.',
   'De poolvas is een meester in overleven onder extreme arctische omstandigheden. Zijn dikke vacht verandert van kleur van wit in de winter naar bruin of grijs in de zomer. Het kan temperaturen weerstaan tot -70°C.',
   'Le renard arctique est un maître de la survie dans des conditions arctiques extrêmes. Sa fourrure épaisse change de couleur du blanc en hiver au brun ou gris en été. Il peut résister à des températures allant jusqu\'à -70°C.',
   'El zorro ártico es un maestro de la supervivencia en condiciones árticas extremas. Su grueso pelaje cambia de color del blanco en invierno al marrón o gris en verano. Puede resistir temperaturas de hasta -70°C.'],
  [708, 'Arktisk ulv', 'Arctische wolf', 'Loup arctique', 'Lobo ártico',
   'Den arktiske ulv er en underart af ulven tilpasset til det arktiske miljø. Den lever i de øde tundraer i det høje arktis, hvor den jager moskusokser og rensdyr. Den kan modstå hårde arktiske vintre.',
   'De arctische wolf is een ondersoort van de wolf die is aangepast aan het arctische milieu. Het leeft in de verlaten toendra van het hoge arctis, waar het op muskusossen en rendieren jaagt. Het kan harde arctische winters weerstaan.',
   'Le loup arctique est une sous-espèce du loup adaptée à l\'environnement arctique. Il vit dans les toundras désolées de l\'Arctique élevé, où il chasse les bœufs musqués et les caribous. Il peut résister aux durs hivers arctiques.',
   'El lobo ártico es una subespecie del lobo adaptada al entorno ártico. Vive en las desoladas tundras del Ártico alto, donde caza bueyes almizcleros y caribús. Puede resistir los duros inviernos árticos.'],
  [709, 'Moskusokse', 'Muskusos', 'Bœuf musqué', 'Buey almizclero',
   'Moskusoksen er et imponerende dyr med en massiv krop dækket af lang, tæt uldhår. Den har overlevet i Arktis siden istiden og er tilpasset til ekstremt kolde temperaturer. Hannerne kæmper dramatisk om brunstperioden.',
   'De muskusos is een indrukwekkend dier met een massief lichaam bedekt met lang, dicht wolhaar. Het heeft overleefd in het Arctisch gebied sinds de ijstijd en is aangepast aan extreem koude temperaturen. Mannetjes vechten dramatisch tijdens de bronst.',
   'Le bœuf musqué est un animal impressionnant avec un corps massif couvert de longs poils laineux denses. Il a survécu dans l\'Arctique depuis l\'ère glaciaire et est adapté aux températures extrêmement froides. Les mâles se battent dramatiquement pendant le rut.',
   'El buey almizclero es un impresionante animal con un cuerpo masivo cubierto de largo y denso pelo lanoso. Ha sobrevivido en el Ártico desde la era glacial y está adaptado a temperaturas extremadamente frías. Los machos luchan dramáticamente durante el celo.'],
  [710, 'Rensdyr', 'Rendier', 'Renne', 'Reno',
   'Rensdyret er det eneste hjorteartede dyr, hvor begge køn bærer gevir. Det er perfekt tilpasset til livet i den arktiske tundra og har brede, hule hover der hjælper med at grave i sne for at finde planter.',
   'Het rendier is het enige hertachtige dier waarbij beide geslachten geweien dragen. Het is perfect aangepast aan het leven in de arctische toendra en heeft brede, holle hoeven die helpen graven in de sneeuw om planten te vinden.',
   'Le renne est le seul cervidé où les deux sexes portent des bois. Il est parfaitement adapté à la vie dans la toundra arctique et a de larges sabots creux qui aident à creuser dans la neige pour trouver des plantes.',
   'El reno es el único cérvido donde ambos sexos portan astas. Está perfectamente adaptado a la vida en la tundra ártica y tiene cascos anchos y huecos que ayudan a excavar en la nieve para encontrar plantas.'],
  [711, 'Hare (arktisk)', 'Poolhaas', 'Lièvre arctique', 'Liebre ártica',
   'Den arktiske hare er en stor hare tilpasset til de kolde arktiske forholder. Dens pels skifter farve fra hvid om vinteren til grå-brun om sommeren. Den er en hurtig løber og kan nå hastigheder på 60 km/t.',
   'De poolhaas is een grote haas aangepast aan de koude arctische omstandigheden. Zijn vacht verandert van kleur van wit in de winter naar grijsbruin in de zomer. Het is een snelle loper en kan snelheden bereiken van 60 km/u.',
   'Le lièvre arctique est un grand lièvre adapté aux conditions arctiques froides. Sa fourrure change de couleur du blanc en hiver au gris-brun en été. C\'est un coureur rapide qui peut atteindre des vitesses de 60 km/h.',
   'La liebre ártica es una gran liebre adaptada a las frías condiciones árticas. Su pelaje cambia de color del blanco en invierno al gris-marrón en verano. Es un corredor rápido que puede alcanzar velocidades de 60 km/h.'],
  [712, 'Lemming', 'Lemming', 'Lemming', 'Lemming',
   'Lemmingen er et lille nager, der er berømt for sine massive migrationer og fejlagtigt berygtet for at kaste sig ud fra klipper. Deres bestande svinger dramatisk i cykler, der påvirker hele det arktiske fødekæde.',
   'De lemming is een klein knaagdier dat beroemd is om zijn massale migraties en ten onrechte berucht is om zichzelf van klippen te gooien. Hun populaties schommelen dramatisch in cycli die de hele arctische voedselketen beïnvloeden.',
   'Le lemming est un petit rongeur célèbre pour ses migrations massives et faussement réputé pour se jeter des falaises. Leurs populations fluctuent dramatiquement en cycles qui affectent toute la chaîne alimentaire arctique.',
   'El lemming es un pequeño roedor famoso por sus masivas migraciones y falsamente conocido por arrojarse desde acantilados. Sus poblaciones fluctúan dramáticamente en ciclos que afectan toda la cadena alimentaria ártica.'],
  [713, 'Sneleopard', 'Sneeuwluipaard', 'Léopard des neiges', 'Leopardo de las nieves',
   'Sneleoparden er en af Asiens mest undvigende store katte og lever i de bjerge og plateau\'er i Centralasien. Den er fortrinligt tilpasset til kold, bjergagtig terræn og er et symbol på styrke og skønhed.',
   'De sneeuwluipaard is een van Azië\'s meest ongrijpbare grote katten en leeft in de bergen en plateaus van Centraal-Azië. Het is uitstekend aangepast aan koud, bergachtig terrein en is een symbool van kracht en schoonheid.',
   'Le léopard des neiges est l\'un des grands félins les plus insaisissables d\'Asie et vit dans les montagnes et les plateaux d\'Asie centrale. Il est parfaitement adapté au terrain montagneux froid et est un symbole de force et de beauté.',
   'El leopardo de las nieves es uno de los grandes felinos más esquivos de Asia y vive en las montañas y mesetas de Asia Central. Está perfectamente adaptado al terreno montañoso frío y es un símbolo de fuerza y belleza.'],
  [714, 'Narval', 'Narval', 'Narval', 'Narval',
   'Narvalen er en arktisk hval berømt for sin lange, spiralformede stød. Faktisk er dette et forlænget fortand. Narvalen bruger det til at kommunikere og muligvis til at navigere i det arktiske hav.',
   'De narwal is een arctische walvis beroemd om zijn lange, spiraalvormige slagtand. In werkelijkheid is dit een verlengde voortand. De narwal gebruikt het om te communiceren en mogelijk om te navigeren in de arctische zee.',
   'Le narval est une baleine arctique célèbre pour sa longue défense spiralée. En réalité, il s\'agit d\'une dent de devant allongée. Le narval l\'utilise pour communiquer et peut-être pour naviguer dans la mer arctique.',
   'El narval es una ballena ártica famosa por su larga y espiral defensa. En realidad es un diente delantero alargado. El narval lo usa para comunicarse y posiblemente para navegar en el mar ártico.'],
  [715, 'Belugahval', 'Belugawalvis', 'Béluga', 'Beluga',
   'Belugaen, også kaldet "hvid hval", er en arktisk og subarktisk hval kendetegnet ved sin kremlede hvide farve og manglen på en rygfinne. Den er ekstremt social og kommunikerer med et rigt udvalg af lyde.',
   'De beluga, ook wel "witte walvis" genoemd, is een arctische en subarctische walvis die wordt gekenmerkt door zijn crèmekleurige witte kleur en het ontbreken van een rugvin. Het is uiterst sociaal en communiceert met een rijke verscheidenheid aan geluiden.',
   'Le béluga, également appelé "baleine blanche", est une baleine arctique et subarctique caractérisée par sa couleur blanc crème et l\'absence de nageoire dorsale. Il est extrêmement social et communique avec une riche variété de sons.',
   'La beluga, también llamada "ballena blanca", es una ballena ártica y subártica caracterizada por su color blanco cremoso y la ausencia de aleta dorsal. Es extremadamente social y se comunica con una rica variedad de sonidos.'],
  [716, 'Ork (Spækhugger)', 'Orka', 'Orque', 'Orca',
   'Orcaen, eller spækhuggeren, er den største delfin i verden og er en mester rovdyr på toppen af havets fødekæde. Dens intelligens og sociale kompleksitet har gjort den til et ikonisk symbol på havets kraft.',
   'De orka, of de zwaardwalvis, is de grootste dolfijn ter wereld en is een meesterroofdier bovenaan de voedselketen van de zee. Zijn intelligentie en sociale complexiteit hebben het tot een iconisch symbool van de kracht van de zee gemaakt.',
   'L\'orque, ou épaulard, est le plus grand dauphin du monde et est un prédateur maître au sommet de la chaîne alimentaire de la mer. Son intelligence et sa complexité sociale en ont fait un symbole emblématique de la puissance de la mer.',
   'La orca, o ballena asesina, es el delfín más grande del mundo y es un depredador maestro en la cima de la cadena alimentaria del mar. Su inteligencia y complejidad social la han convertido en un símbolo icónico del poder del mar.'],
  [717, 'Søløve', 'Zeeleeuw', 'Otarie', 'León marino',
   'Søløver er kendetegnet ved deres evne til at bevæge sig på alle fire lemmer på land, hvilket adskiller dem fra sæler. De er ekstremt lydige og bruges til marineopgaver og akrobatiske shows.',
   'Zeeleeuwen worden gekenmerkt door hun vermogen om op alle vier de ledematen op het land te bewegen, wat hen onderscheidt van zeehonden. Ze zijn uiterst gehoorzaam en worden gebruikt voor marineoperaties en acrobatische shows.',
   'Les otaries sont caractérisées par leur capacité à se déplacer sur leurs quatre membres sur terre, ce qui les distingue des phoques. Elles sont extrêmement obéissantes et sont utilisées pour des opérations navales et des spectacles acrobatiques.',
   'Los leones marinos se caracterizan por su capacidad de moverse sobre sus cuatro extremidades en tierra, lo que los distingue de las focas. Son extremadamente obedientes y se usan para operaciones navales y espectáculos acrobáticos.'],
  [718, 'Pungdyr (antarktisk)', 'Zuidelijke olifantzeehond', 'Éléphant de mer du sud', 'Elefante marino del sur',
   'Den sydlige søelefant er det største rovdyr i ordenen Pinnipedia og kan veje op til 4 ton. Hannerne har en karakteristisk snabelagtig næse og kæmper voldsomt om territorium og hunner i yngletiden.',
   'De zuidelijke zeeolifant is het grootste roofdier in de orde Pinnipedia en kan tot 4 ton wegen. Mannetjes hebben een kenmerkende slurf-achtige neus en vechten heftig om territorium en vrouwtjes tijdens het broedseizoen.',
   'L\'éléphant de mer du sud est le plus grand prédateur de l\'ordre des Pinnipèdes et peut peser jusqu\'à 4 tonnes. Les mâles ont un nez en forme de trompe caractéristique et se battent violemment pour le territoire et les femelles pendant la saison de reproduction.',
   'El elefante marino del sur es el mayor depredador del orden Pinnipedia y puede pesar hasta 4 toneladas. Los machos tienen una nariz característica en forma de trompa y luchan violentamente por el territorio y las hembras durante la temporada de cría.'],
  [719, 'Albatros', 'Albatros', 'Albatros', 'Albatros',
   'Albatrosserne har det største vingefang af alle fugle og kan nå op til 3,7 meter. De er mestre i at glide på havsvinds og kan tilbagelægge tusindvis af kilometer uden at slå med vingerne.',
   'Albatrossen hebben de grootste vleugelspanwijdte van alle vogels en kunnen tot 3,7 meter bereiken. Ze zijn meesters in het glijden op zeewinden en kunnen duizenden kilometers afleggen zonder met hun vleugels te slaan.',
   'Les albatros ont la plus grande envergure de tous les oiseaux et peuvent atteindre jusqu\'à 3,7 mètres. Ils sont des maîtres du vol plané sur les vents marins et peuvent parcourir des milliers de kilomètres sans battre des ailes.',
   'Los albatros tienen la mayor envergadura de todas las aves y pueden alcanzar hasta 3,7 metros. Son maestros en planear con los vientos marinos y pueden recorrer miles de kilómetros sin batir sus alas.'],
  [720, 'Vidunderlig fugl', 'Ijsduiker', 'Plongeon arctique', 'Colimbo ártico',
   'Den arktiske lom er en fremragende dykker og svømmer og tilpasser sig perfekt til livet på det kolde hav. Den er kendetegnet ved sin karakteristiske skakternede sort-hvide plovning og sin melankolske sang.',
   'De arctische duiker is een uitstekende duiker en zwemmer en past zich perfect aan aan het leven op de koude zee. Het wordt gekenmerkt door zijn kenmerkende geblokte zwart-witte kleurpatroon en zijn melancholische zang.',
   'Le plongeon arctique est un excellent plongeur et nageur et s\'adapte parfaitement à la vie en mer froide. Il est caractérisé par son plumage à damier noir et blanc caractéristique et son chant mélancolique.',
   'El colimbo ártico es un excelente buceador y nadador que se adapta perfectamente a la vida en el frío mar. Se caracteriza por su característico plumaje a cuadros blanco y negro y su canto melancólico.'],
  [721, 'Hvalros (unge)', 'Jonge walrus', 'Bébé morse', 'Morsa joven',
   'Unge hvalrosser er afhængige af deres mødre i op til to år og er sociale dyr, der er hurtige til at lære. De tilbringer meget tid i vandet og øver sig i at svømme og dykke under beskyttelse af flokken.',
   'Jonge walrussen zijn tot twee jaar afhankelijk van hun moeders en zijn sociale dieren die snel leren. Ze brengen veel tijd in het water door en oefenen zwemmen en duiken onder bescherming van de kudde.',
   'Les jeunes morses dépendent de leurs mères pendant jusqu\'à deux ans et sont des animaux sociaux qui apprennent vite. Ils passent beaucoup de temps dans l\'eau à pratiquer la nage et la plongée sous la protection du troupeau.',
   'Las jóvenes morsas dependen de sus madres hasta dos años y son animales sociales que aprenden rápidamente. Pasan mucho tiempo en el agua practicando natación y buceo bajo la protección de la manada.'],
  [722, 'Arktisk tern', 'Noordse stern', 'Sterne arctique', 'Charrán ártico',
   'Den arktiske terne holder verdens længste migration og rejser hvert år fra Arktis til Antarktis og tilbage — en tur på op til 90.000 km. Den ser mere dagslys end noget andet dyr på Jordend.',
   'De Noordse stern maakt de langste migratie ter wereld en reist elk jaar van het Arctisch gebied naar Antarctica en terug — een reis van maximaal 90.000 km. Het ziet meer daglicht dan enig ander dier op aarde.',
   'La sterne arctique effectue la plus longue migration du monde et voyage chaque année de l\'Arctique à l\'Antarctique et retour — un voyage allant jusqu\'à 90 000 km. Elle voit plus de lumière du jour que tout autre animal sur Terre.',
   'El charrán ártico realiza la migración más larga del mundo y viaja cada año del Ártico a la Antártida y de regreso, un viaje de hasta 90.000 km. Ve más luz diurna que cualquier otro animal en la Tierra.'],
  [723, 'Isbjørn (arktisk)', 'Poolbeer', 'Ours blanc', 'Oso blanco',
   'Den hvide bjørn er et andet navn for isbjørnen og er et ikonisk symbol på Arktis. Klimaforandringerne udgør en alvorlig trussel mod denne art, da havisen, den afhænger af, smelter hurtigere end nogensinde.',
   'De witte beer is een andere naam voor de ijsbeer en is een iconisch symbool van het Arctisch gebied. Klimaatverandering vormt een ernstige bedreiging voor deze soort, omdat het zee-ijs waarvan het afhankelijk is, sneller smelt dan ooit tevoren.',
   'L\'ours blanc est un autre nom pour l\'ours polaire et est un symbole emblématique de l\'Arctique. Le changement climatique représente une menace sérieuse pour cette espèce, car la banquise dont elle dépend fond plus vite que jamais.',
   'El oso blanco es otro nombre para el oso polar y es un símbolo icónico del Ártico. El cambio climático representa una grave amenaza para esta especie, ya que el hielo marino del que depende se derrite más rápido que nunca.'],
  [724, 'Arktisk hund (Samojet)', 'Samojeed', 'Samoyède', 'Samoyedo',
   'Samoyeden er en hunderace med oprindelse hos de sibiriske samojed-nomader. Den bruges traditionelt til slæde- og vogterhunde og har en tyk, hvid dobbeltpels der holder dem varme i ekstreme kulde.',
   'De Samojeed is een hondenras afkomstig van de Siberische Samojed-nomaden. Het wordt traditioneel gebruikt als slee- en herdershond en heeft een dikke, witte dubbele vacht die hen warm houdt in extreme kou.',
   'Le Samoyède est une race de chien originaire des nomades sibériens Samoyèdes. Il est traditionnellement utilisé comme chien de traîneau et de berger et possède un épais double manteau blanc qui le garde au chaud dans les froids extrêmes.',
   'El samoyedo es una raza de perro originaria de los nómadas siberianos Samoyedos. Se usa tradicionalmente como perro de trineo y pastor y tiene un grueso doble pelaje blanco que los mantiene calientes en el frío extremo.'],
  [725, 'Kryolitisk fisk', 'Ijsvis', 'Poisson des glaces', 'Pez de hielo',
   'Isfisken er en usædvanlig fisk fra de kolde sydpolske have. Den har ikke hemoglobin i blodet men har i stedet specialiserede proteiner, der forhindrer dens blod i at fryse. Dens blod er bogstaveligt talt gennemsigtigt.',
   'De ijsvis is een ongewone vis uit de koude zuidpoolzeeën. Het heeft geen hemoglobine in het bloed, maar heeft in plaats daarvan gespecialiseerde eiwitten die voorkomen dat het bloed bevriest. Zijn bloed is letterlijk transparant.',
   'Le poisson des glaces est un poisson inhabituel des mers antarctiques froides. Il n\'a pas d\'hémoglobine dans le sang mais possède à la place des protéines spécialisées qui empêchent son sang de geler. Son sang est littéralement transparent.',
   'El pez de hielo es un pez inusual de los fríos mares antárticos. No tiene hemoglobina en la sangre sino proteínas especializadas que impiden que su sangre se congele. Su sangre es literalmente transparente.'],

  // ===== BIOME 800: WASSER =====
  [801, 'Stor hvid haj', 'Witte haai', 'Grand requin blanc', 'Gran tiburón blanco',
   'Den store hvide haj er et af havets mest frygtede rovdyr. Den kan vokse til over 6 meter og er udstyret med rækker af udskiftelige tænder. Den er faktisk ikke specielt interesseret i at spise mennesker.',
   'De witte haai is een van de meest gevreesde roofdieren van de zee. Het kan meer dan 6 meter groeien en is uitgerust met rijen verwisselbare tanden. Het is eigenlijk niet bijzonder geïnteresseerd in het eten van mensen.',
   'Le grand requin blanc est l\'un des prédateurs les plus redoutés de la mer. Il peut atteindre plus de 6 mètres et est équipé de rangées de dents remplaçables. Il n\'est en réalité pas particulièrement intéressé à manger des humains.',
   'El gran tiburón blanco es uno de los depredadores más temidos del mar. Puede crecer a más de 6 metros y está equipado con filas de dientes reemplazables. En realidad no está particularmente interesado en comer humanos.'],
  [802, 'Hummer', 'Kreeft', 'Homard', 'Langosta',
   'Hummeren er et fascinerende krebsdyr med et hårdt ydre skelet. Den er udødelighedsbevidst og vokser faktisk hele livet igennem — biologisk ældes den næsten ikke. Den kan leve i over 100 år.',
   'De kreeft is een fascinerend schaaldier met een hard uitwendig skelet. Het is onsterfelijkheidsbewust en groeit zijn hele leven — het veroudert biologisch bijna niet. Het kan meer dan 100 jaar leven.',
   'Le homard est un crustacé fascinant avec un squelette externe dur. Il est biologiquement conscient de l\'immortalité et grandit tout au long de sa vie — il vieillit biologiquement presque pas. Il peut vivre plus de 100 ans.',
   'La langosta es un fascinante crustáceo con un esqueleto externo duro. Es biológicamente consciente de la inmortalidad y crece a lo largo de toda su vida: biológicamente casi no envejece. Puede vivir más de 100 años.'],
  [803, 'Søhest', 'Zeepaard', 'Hippocampe', 'Caballito de mar',
   'Søhesten er en unik fisk, hvor hannerne bærer og føder ungerne. Den er en langsom svømmer og bruger sin griberhalede til at holde fast i koraller og havgræs for at undgå at blive revet væk af strømme.',
   'Het zeepaard is een unieke vis waarbij de mannetjes de jongen dragen en baren. Het is een langzame zwemmer en gebruikt zijn grijpstaart om zich vast te houden aan koralen en zeegras om te voorkomen dat het door stromingen wordt meegesleurd.',
   'L\'hippocampe est un poisson unique où les mâles portent et donnent naissance aux jeunes. C\'est un nageur lent qui utilise sa queue préhensile pour s\'accrocher aux coraux et aux herbiers marins pour éviter d\'être emporté par les courants.',
   'El caballito de mar es un pez único donde los machos cargan y dan a luz a las crías. Es un nadador lento que usa su cola prensil para aferrarse a corales y praderas marinas para evitar ser arrastrado por las corrientes.'],
  [804, 'Otøm', 'Zeeotter', 'Loutre de mer', 'Nutria marina',
   'Havotteren er en lille pattedyr, der lever primært i havet og er kendt for at sove flydende på ryggen, ofte holder i hænderne med en partner. Den er een af de få dyr, der bruger redskaber.',
   'De zeeotter is een klein zoogdier dat voornamelijk in de zee leeft en bekend staat om het slapend op zijn rug te drijven, vaak elkaars hand vasthoudend met een partner. Het is een van de weinige dieren die gereedschap gebruiken.',
   'La loutre de mer est un petit mammifère qui vit principalement dans la mer et est connu pour dormir flottant sur le dos, tenant souvent la main d\'un partenaire. C\'est l\'un des rares animaux à utiliser des outils.',
   'La nutria marina es un pequeño mamífero que vive principalmente en el mar y es conocida por dormir flotando boca arriba, a menudo tomando de la mano a una pareja. Es uno de los pocos animales que usan herramientas.'],
  [805, 'Delfin', 'Dolfijn', 'Dauphin', 'Delfín',
   'Delfiner er ekstremt intelligente havpattedyr med komplekse sociale strukturer. De kommunikerer ved hjælp af et rigt repertoire af kliks, fløjt og andre lyde. De er kendte for at hjælpe nødlidende svømmere.',
   'Dolfijnen zijn uiterst intelligente zeezoogdieren met complexe sociale structuren. Ze communiceren met behulp van een rijk repertoire van klikken, fluiten en andere geluiden. Ze staan bekend om het helpen van zwemmers in nood.',
   'Les dauphins sont des mammifères marins extrêmement intelligents avec des structures sociales complexes. Ils communiquent à l\'aide d\'un riche répertoire de clics, de sifflements et d\'autres sons. Ils sont connus pour aider les nageurs en détresse.',
   'Los delfines son mamíferos marinos extremadamente inteligentes con estructuras sociales complejas. Se comunican mediante un rico repertorio de clics, silbidos y otros sonidos. Son conocidos por ayudar a nadadores en dificultades.'],
  [806, 'Blaahval', 'Blauwe vinvis', 'Baleine bleue', 'Ballena azul',
   'Blåhvalen er det største dyr, der nogensinde har levet på Jordendens overflade. Den kan blive op til 33 meter lang og veje over 150 ton. Dens hjerte er på størrelse med en lille bil.',
   'De blauwe vinvis is het grootste dier dat ooit op het aardoppervlak heeft geleefd. Het kan tot 33 meter lang worden en meer dan 150 ton wegen. Zijn hart is zo groot als een kleine auto.',
   'La baleine bleue est le plus grand animal ayant jamais vécu à la surface de la Terre. Elle peut atteindre jusqu\'à 33 mètres de longueur et peser plus de 150 tonnes. Son cœur est de la taille d\'une petite voiture.',
   'La ballena azul es el animal más grande que ha vivido jamás en la superficie de la Tierra. Puede alcanzar hasta 33 metros de longitud y pesar más de 150 toneladas. Su corazón es del tamaño de un coche pequeño.'],
  [807, 'Kæmpeblæsprutte', 'Reuzeninktvis', 'Seiche géante', 'Sepia gigante',
   'Blæksprutten er et yderst intelligent dyr med et komplekst nervesystem. Den kan skifte farve og mønster på sin hud på kun millisekunder og er en mester i camouflage og kommunikation.',
   'De inktvis is een uiterst intelligent dier met een complex zenuwstelsel. Het kan in milliseconden van kleur en patroon op zijn huid veranderen en is een meester in camouflage en communicatie.',
   'Le calmar est un animal extrêmement intelligent avec un système nerveux complexe. Il peut changer de couleur et de motif sur sa peau en quelques millisecondes et est un maître du camouflage et de la communication.',
   'El calamar es un animal extremadamente inteligente con un sistema nervioso complejo. Puede cambiar de color y patrón en su piel en solo milisegundos y es un maestro del camuflaje y la comunicación.'],
  [808, 'Havskildpadde', 'Zeeschildpad', 'Tortue de mer', 'Tortuga marina',
   'Havskildpadder er overlevende fra en svunden tid og har ikke ændret sig markant i over 100 millioner år. De navigerer utroligt præcist og vender altid tilbage til den strand, hvor de blev født, for at lægge æg.',
   'Zeeschildpadden zijn overlevenden uit een vergane tijd en zijn al meer dan 100 miljoen jaar niet significant veranderd. Ze navigeren ongelooflijk nauwkeurig en keren altijd terug naar het strand waar ze zijn geboren om eieren te leggen.',
   'Les tortues de mer sont des survivants d\'une époque révolue et n\'ont pas changé de manière significative depuis plus de 100 millions d\'années. Elles naviguent avec une précision incroyable et reviennent toujours sur la plage où elles sont nées pour pondre leurs œufs.',
   'Las tortugas marinas son supervivientes de una época pasada y no han cambiado significativamente en más de 100 millones de años. Navegan con increíble precisión y siempre regresan a la playa donde nacieron para poner huevos.'],
  [809, 'Koralrev', 'Koraalrif', 'Récif corallien', 'Arrecife de coral',
   'Koralrev er havets regnskov og huser op til 25% af alle havarter på kun 0,1% af havets overflade. Koraller er faktisk dyr, der lever i symbiose med fotosyntetiserende alger. Mange er truede af klimaforandringer.',
   'Koraalriffen zijn het regenwoud van de zee en herbergen tot 25% van alle zeesoorten op slechts 0,1% van het oceaanoppervlak. Koralen zijn eigenlijk dieren die in symbiose leven met fotosynthetiserende algen. Velen worden bedreigd door klimaatverandering.',
   'Les récifs coralliens sont la forêt tropicale de la mer et abritent jusqu\'à 25% de toutes les espèces marines sur seulement 0,1% de la surface de l\'océan. Les coraux sont en réalité des animaux vivant en symbiose avec des algues photosynthétiques. Beaucoup sont menacés par le changement climatique.',
   'Los arrecifes de coral son la selva tropical del mar y albergan hasta el 25% de todas las especies marinas en solo el 0,1% de la superficie del océano. Los corales son en realidad animales que viven en simbiosis con algas fotosintéticas. Muchos están amenazados por el cambio climático.'],
  [810, 'Blæksprutte (ottearmet)', 'Octopus', 'Pieuvre', 'Pulpo',
   'Blæksprutten er et af de mest intelligente hvirvelløse dyr på Jordendens overflade. Den har tre hjerter, blåt blod og kan ændre sin farve og tekstur på millisekunder. Hvert af dens otte arme har sin egen intelligens.',
   'De octopus is een van de meest intelligente ongewervelde dieren op aarde. Het heeft drie harten, blauw bloed en kan in milliseconden van kleur en textuur veranderen. Elk van zijn acht armen heeft zijn eigen intelligentie.',
   'La pieuvre est l\'un des animaux invertébrés les plus intelligents de la Terre. Elle a trois cœurs, du sang bleu et peut changer de couleur et de texture en millisecondes. Chacun de ses huit bras a sa propre intelligence.',
   'El pulpo es uno de los invertebrados más inteligentes de la Tierra. Tiene tres corazones, sangre azul y puede cambiar de color y textura en milisegundos. Cada uno de sus ocho brazos tiene su propia inteligencia.'],
  [811, 'Havaborre', 'Zeebaars', 'Bar commun', 'Lubina europea',
   'Havaborrens er en populær sportsfisk med et sølvskinnende udseende. Den er en aktiv jæger og lever i grupper i kystvande. Den er en vigtig kommerciel fisk i mange europæiske lande.',
   'De zeebaars is een populaire sportvissen met een zilverig uiterlijk. Het is een actieve jager en leeft in groepen in kustwateren. Het is een belangrijke commerciële vis in veel Europese landen.',
   'Le bar commun est un poisson sportif populaire à l\'apparence argentée. C\'est un chasseur actif qui vit en groupes dans les eaux côtières. C\'est un poisson commercial important dans de nombreux pays européens.',
   'La lubina europea es un popular pez deportivo con apariencia plateada. Es un cazador activo que vive en grupos en aguas costeras. Es un pez comercial importante en muchos países europeos.'],
  [812, 'Laks', 'Zalm', 'Saumon', 'Salmón',
   'Laksen er berømt for sin episke rejse fra havet tilbage til sin fødeguld for at yngle. Denne rejse mod strømen kan være over 1000 km lang. Laksen spiser ikke under denne vandring og lever af sine fedtreserver.',
   'De zalm is beroemd om zijn epische reis van de zee terug naar zijn geboortewater om te paaien. Deze tocht stroomopwaarts kan meer dan 1000 km lang zijn. De zalm eet niet tijdens deze tocht en leeft van zijn vetreserves.',
   'Le saumon est célèbre pour son voyage épique de la mer jusqu\'à ses eaux natales pour se reproduire. Ce voyage contre le courant peut dépasser 1000 km. Le saumon ne mange pas pendant cette migration et vit de ses réserves de graisses.',
   'El salmón es famoso por su épico viaje del mar de regreso a sus aguas natales para reproducirse. Este viaje contra la corriente puede superar los 1000 km. El salmón no come durante esta migración y vive de sus reservas de grasa.'],
  [813, 'Tun', 'Tonijn', 'Thon', 'Atún',
   'Tunen er en af havets hurtigste fisk og kan svømme med hastigheder på over 70 km/t. Den er en varmblodighed fisk, der kan opretholde en højere kropstemperatur end det omgivende vand, hvilket giver muskeleffektivitet.',
   'De tonijn is een van de snelste vissen van de zee en kan zwemmen met snelheden van meer dan 70 km/u. Het is een warmbloedige vis die een hogere lichaamstemperatuur kan handhaven dan het omringende water, wat spierefficiëntie geeft.',
   'Le thon est l\'un des poissons les plus rapides de la mer et peut nager à des vitesses dépassant 70 km/h. C\'est un poisson à sang chaud qui peut maintenir une température corporelle plus élevée que l\'eau environnante, ce qui lui donne une efficacité musculaire.',
   'El atún es uno de los peces más rápidos del mar y puede nadar a velocidades superiores a 70 km/h. Es un pez de sangre caliente que puede mantener una temperatura corporal más alta que el agua circundante, lo que le da eficiencia muscular.'],
  [814, 'Hornfisk', 'Geep', 'Orphie', 'Aguja',
   'Hornfiskens er en langstrakt, sølvskinnende fisk med et karakteristisk langt næb. Den lever i åbent hav og er berømt for sin evne til at springe over vandoverfladen. Den er en populær sportsfisk.',
   'De geep is een langgerekte, zilverachtige vis met een karakteristieke lange snavel. Het leeft in open zee en staat bekend om zijn vermogen om over het wateroppervlak te springen. Het is een populaire sportvissen.',
   'L\'orphie est un poisson allongé aux reflets argentés avec un long bec caractéristique. Il vit en haute mer et est connu pour sa capacité à sauter au-dessus de la surface de l\'eau. C\'est un poisson sportif populaire.',
   'La aguja es un pez alargado y plateado con un característico pico largo. Vive en mar abierto y es conocida por su capacidad de saltar sobre la superficie del agua. Es un popular pez deportivo.'],
  [815, 'Sværdfisk', 'Zwaardvis', 'Espadon', 'Pez espada',
   'Sværdfisken er en stor, hurtig rovfisk opkaldt efter dens lange, sværdlignende overbid. Den er en af de hurtigste fisk i havet og kan svømme med hastigheder på over 97 km/t.',
   'De zwaardvis is een grote, snelle roofvis vernoemd naar zijn lange, zwaard-achtige bovenbek. Het is een van de snelste vissen in de zee en kan zwemmen met snelheden van meer dan 97 km/u.',
   'L\'espadon est un grand poisson prédateur rapide nommé d\'après son long museau supérieur en forme d\'épée. C\'est l\'un des poissons les plus rapides de la mer et peut nager à des vitesses dépassant 97 km/h.',
   'El pez espada es un gran pez depredador rápido nombrado por su largo pico superior en forma de espada. Es uno de los peces más rápidos del mar y puede nadar a velocidades superiores a 97 km/h.'],
  [816, 'Sæl (monket)', 'Monniksrob', 'Phoque moine', 'Foca monje',
   'Munksælen er en af de mest truede havpattedyr i verden. I modsætning til andre sæler trives den i varme Middelhavsomgivelser. Den er et sjældent syn og kræver aktiv bevaringsindsats for at overleve.',
   'De monniksrob is een van de meest bedreigde zeezoogdieren ter wereld. In tegenstelling tot andere zeehonden gedijt het in warme Middellandse Zee-omgevingen. Het is een zeldzame aanblik en vereist actieve conserveringsacties om te overleven.',
   'Le phoque moine est l\'un des mammifères marins les plus menacés du monde. Contrairement aux autres phoques, il prospère dans les environnements chauds de la Méditerranée. C\'est une vue rare et il nécessite des efforts de conservation actifs pour survivre.',
   'La foca monje es uno de los mamíferos marinos más amenazados del mundo. A diferencia de otras focas, prospera en los cálidos entornos mediterráneos. Es una vista rara y requiere esfuerzos activos de conservación para sobrevivir.'],
  [817, 'Puffin', 'Papegaaiduiker', 'Macareux moine', 'Frailecillo atlántico',
   'Lunden er en farverig havfugl med en karakteristisk orange næb, der bruges til at bære fisk. Den er en exceptionel svømmer og dykker og kan nå dybder på over 60 meter. Den lever i kystklipperederkolonier.',
   'De papegaaiduiker is een kleurrijke zeevogel met een kenmerkende oranje snavel die wordt gebruikt om vissen te dragen. Het is een uitzonderlijke zwemmer en duiker en kan diepten bereiken van meer dan 60 meter. Het leeft in kustklipperederkolonier.',
   'Le macareux moine est un oiseau de mer coloré avec un bec orange caractéristique utilisé pour transporter les poissons. C\'est un nageur et plongeur exceptionnel qui peut atteindre des profondeurs de plus de 60 mètres. Il vit dans des colonies nichant sur les falaises côtières.',
   'El frailecillo atlántico es un colorido pájaro marino con un característico pico naranja usado para transportar peces. Es un nadador y buceador excepcional que puede alcanzar profundidades de más de 60 metros. Vive en colonias que anidan en acantilados costeros.'],
  [818, 'Havmåge', 'Zilvermeeuw', 'Goéland argenté', 'Gaviota argéntea',
   'Sølvmågen er en af de mest kendte og udbredte mågearter i Europa. Den er et opportunistisk dyr, der lever af alt fra fisk til affald. Den er ekspert i at bruge termik til at svæve i timesvis.',
   'De zilvermeeuw is een van de meest bekende en wijdverbreide meeuwensoorten in Europa. Het is een opportunistisch dier dat leeft van alles van vissen tot afval. Het is een expert in het gebruik van thermiek om uren te zweven.',
   'Le goéland argenté est l\'une des espèces de mouettes les plus connues et répandues en Europe. C\'est un animal opportuniste qui vit de tout, des poissons aux déchets. Il est expert dans l\'utilisation des thermiques pour planer pendant des heures.',
   'La gaviota argéntea es una de las especies de gaviota más conocidas y extendidas en Europa. Es un animal oportunista que vive de todo, desde peces hasta residuos. Es experta en usar las térmicas para planear durante horas.'],
  [819, 'Hvid haj', 'Bulhaai', 'Requin bouledogue', 'Tiburón toro',
   'Tyrehajen er en af de farligste hajarter for mennesker på grund af dens aggressive natur og tilbøjelighed til at svømme ind i lavt, varmt vand og endda i floder. Den kan tolerere ferskvand i lange perioder.',
   'De bulhaai is een van de gevaarlijkste haaiensoorten voor mensen vanwege zijn agressieve aard en neiging om in ondiep, warm water en zelfs in rivieren te zwemmen. Het kan zoet water voor lange perioden verdragen.',
   'Le requin bouledogue est l\'une des espèces de requins les plus dangereuses pour les humains en raison de sa nature agressive et de sa tendance à nager dans les eaux peu profondes et chaudes et même dans les rivières. Il peut tolérer l\'eau douce pendant de longues périodes.',
   'El tiburón toro es una de las especies de tiburón más peligrosas para los humanos debido a su naturaleza agresiva y tendencia a nadar en aguas poco profundas y cálidas e incluso en ríos. Puede tolerar el agua dulce durante largos períodos.'],
  [820, 'Lysende maneter', 'Gloeiende kwal', 'Méduse lumineuse', 'Medusa luminosa',
   'Bioluminescerende maneter er et af naturens mest fascinerende fænomener. De producerer lys gennem kemiske reaktioner i kroppen og bruger dette til at tiltrække bytte, afskrække rovdyr og kommunikere.',
   'Bioluminescente kwallen zijn een van de meest fascinerende fenomenen van de natuur. Ze produceren licht door chemische reacties in het lichaam en gebruiken dit om prooi aan te trekken, roofdieren af te schrikken en te communiceren.',
   'Les méduses bioluminescentes sont l\'un des phénomènes les plus fascinants de la nature. Elles produisent de la lumière grâce à des réactions chimiques dans le corps et l\'utilisent pour attirer des proies, dissuader les prédateurs et communiquer.',
   'Las medusas bioluminiscentes son uno de los fenómenos más fascinantes de la naturaleza. Producen luz mediante reacciones químicas en el cuerpo y la usan para atraer presas, ahuyentar depredadores y comunicarse.'],
  [821, 'Kæmpekrabbe', 'Japanse spinkrab', 'Crabe araignée géant', 'Cangrejo araña gigante',
   'Den japanske piratedderkopkrabbe er den største ledyrart i verden med et benspand på op til 3,7 meter. Den lever i dybe havvande og kan leve i over 100 år. Dens lange, slanke ben giver den et spøgelsesagtigt udseende.',
   'De Japanse spinkrab is het grootste geleedpotige ter wereld met een beenspanwijdte van maximaal 3,7 meter. Het leeft in diepe zeeën en kan meer dan 100 jaar leven. Zijn lange, slanke benen geven het een spookachtig uiterlijk.',
   'Le crabe araignée géant est le plus grand arthropode du monde avec une portée de pattes allant jusqu\'à 3,7 mètres. Il vit dans les eaux marines profondes et peut vivre plus de 100 ans. Ses longues et minces pattes lui donnent une apparence fantomatique.',
   'El cangrejo araña gigante es el artrópodo más grande del mundo con una envergadura de hasta 3,7 metros. Vive en aguas marinas profundas y puede vivir más de 100 años. Sus largas y delgadas patas le dan un aspecto fantasmal.'],
  [822, 'Dugong', 'Doejong', 'Dugong', 'Dugongo',
   'Dugongen er tæt beslægtet med havkoen og er den eneste nulevende repræsentant for familien Dugongidae. Den lever af havgræs og er et fredeligt dyr. Dens forside lemmer minder om arme, hvilket kan have inspireret sirene-legender.',
   'De doejong is nauw verwant aan de zeekoe en is de enige levende vertegenwoordiger van de familie Dugongidae. Het leeft van zeegras en is een vredig dier. Zijn voorste ledematen lijken op armen, wat mogelijk de sirene-legendes heeft geïnspireerd.',
   'Le dugong est étroitement lié au lamantin et est le seul représentant vivant de la famille Dugongidae. Il se nourrit d\'herbiers marins et est un animal paisible. Ses membres antérieurs ressemblent à des bras, ce qui a peut-être inspiré les légendes des sirènes.',
   'El dugongo está estrechamente relacionado con el manatí y es el único representante vivo de la familia Dugongidae. Se alimenta de hierba marina y es un animal pacífico. Sus extremidades anteriores parecen brazos, lo que pudo haber inspirado las leyendas de las sirenas.'],
  [823, 'Rokke', 'Rog', 'Raie', 'Raya',
   'Rokker er brusk-fisk nært beslægtede med hajer. De er tilpasset til et liv på havbunden og er flade for at skjule sig i sand. De fleste arter har giftige sporer i halen som forsvar.',
   'Roggen zijn kraakbeenvisssen die nauw verwant zijn aan haaien. Ze zijn aangepast aan een leven op de zeebodem en zijn plat om zich in het zand te verbergen. De meeste soorten hebben giftige stekels in de staart als verdediging.',
   'Les raies sont des poissons cartilagineux étroitement liés aux requins. Ils sont adaptés à une vie sur les fonds marins et sont aplatis pour se cacher dans le sable. La plupart des espèces ont des épines venimeuses dans la queue comme défense.',
   'Las rayas son peces cartilaginosos estrechamente relacionados con los tiburones. Están adaptadas a una vida en el fondo del mar y son planas para esconderse en la arena. La mayoría de las especies tienen espinas venenosas en la cola como defensa.'],
  [824, 'Kobbe', 'Gewone zeehond', 'Phoque commun', 'Foca común',
   'Den almindelige sæl er en af de hyppigst sete havpattedyr i europæiske farvande. Den er nysgerrig af natur og er ofte set på sandbanker. Dens store øjne er tilpasset til at se godt under vand i svagt lys.',
   'De gewone zeehond is een van de meest geziene zeezoogdieren in Europese wateren. Het is van nature nieuwsgierig en wordt vaak gezien op zandbanken. Zijn grote ogen zijn aangepast om goed onder water te zien bij weinig licht.',
   'Le phoque commun est l\'un des mammifères marins les plus souvent vus dans les eaux européennes. Il est curieux par nature et est souvent vu sur les bancs de sable. Ses grands yeux sont adaptés pour bien voir sous l\'eau dans la faible lumière.',
   'La foca común es uno de los mamíferos marinos más vistos en aguas europeas. Es curiosa por naturaleza y a menudo se la ve en bancos de arena. Sus grandes ojos están adaptados para ver bien bajo el agua con poca luz.'],
  [825, 'Havkat', 'Zeekat', 'Seiche', 'Sepia',
   'Sepiaen er et bløddyr tæt beslægtet med blæksprutter. Den er en mester i camouflage og kan ændre sin hud-farve og mønster på millisekunder. Den bruger en indre skal som opdriftskontrol.',
   'De sepia is een weekdier dat nauw verwant is aan de octopus. Het is een meester in camouflage en kan zijn huidkleur en -patroon in milliseconden veranderen. Het gebruikt een binnenste schaal als driftcontrole.',
   'La seiche est un mollusque étroitement lié à la pieuvre. C\'est un maître du camouflage qui peut changer la couleur et le motif de sa peau en quelques millisecondes. Elle utilise une coquille interne comme contrôle de flottabilité.',
   'La sepia es un molusco estrechamente relacionado con el pulpo. Es un maestro del camuflaje que puede cambiar el color y patrón de su piel en milisegundos. Usa una concha interna como control de flotabilidad.'],
  [826, 'Elektrisk ål', 'Elektrische aal', 'Anguille électrique', 'Anguila eléctrica',
   'Den elektriske ål er faktisk ikke en ægte ål, men en fisk der kan generere elektriske stød på op til 600 volt. Den bruger disse stød til at bedøve bytte, forsvare sig og navigere i mudret vand.',
   'De elektrische aal is eigenlijk geen echte aal, maar een vis die elektrische schokken van maximaal 600 volt kan genereren. Het gebruikt deze schokken om prooi te verdoven, zich te verdedigen en te navigeren in troebel water.',
   'L\'anguille électrique n\'est en réalité pas une vraie anguille, mais un poisson capable de générer des chocs électriques allant jusqu\'à 600 volts. Elle utilise ces chocs pour étourdir les proies, se défendre et naviguer dans les eaux boueuses.',
   'La anguila eléctrica en realidad no es una verdadera anguila, sino un pez que puede generar descargas eléctricas de hasta 600 voltios. Usa estas descargas para aturdir presas, defenderse y navegar en aguas turbias.'],
  [827, 'Havørn', 'Zeearend', 'Pygargue à queue blanche', 'Águila pescadora',
   'Havørnen er en imponerende rovfugl med et vingefang på op til 2,4 meter. Den er Europas største ørn og er ekspert i at fange fisk fra vandoverfladen med sine kraftige kløer.',
   'De zeearend is een imposante roofvogel met een vleugelspanwijdte van maximaal 2,4 meter. Het is de grootste arend van Europa en is een expert in het vangen van vissen van het wateroppervlak met zijn krachtige klauwen.',
   'Le pygargue à queue blanche est un rapace impressionnant avec une envergure allant jusqu\'à 2,4 mètres. C\'est le plus grand aigle d\'Europe et il est expert dans la capture de poissons à la surface de l\'eau avec ses puissantes serres.',
   'El águila pescadora es un impresionante rapaz con una envergadura de hasta 2,4 metros. Es el águila más grande de Europa y es experta en capturar peces de la superficie del agua con sus poderosas garras.'],
  [828, 'Makrelfisk', 'Makreel', 'Maquereau', 'Caballa',
   'Makrellen er en sølvglinsende, hurtig stimmefisk fra Nordatlanten. Den er let genkendelig på sine karakteristiske grønne bølgemønstre på ryggen. Den danner store stimer for at beskytte sig mod rovdyr.',
   'De makreel is een zilverachtige, snelle scholvis uit de Noordelijke Atlantische Oceaan. Het is gemakkelijk herkenbaar aan zijn karakteristieke groene golfpatronen op zijn rug. Het vormt grote scholen om zich te beschermen tegen roofdieren.',
   'Le maquereau est un poisson de banc rapide aux reflets argentés de l\'Atlantique Nord. Il est facilement reconnaissable à ses motifs ondulés verts caractéristiques sur le dos. Il forme de grands bancs pour se protéger des prédateurs.',
   'La caballa es un pez de banco rápido y plateado del Atlántico Norte. Es fácilmente reconocible por sus característicos patrones de olas verdes en el dorso. Forma grandes bancos para protegerse de los depredadores.'],
  [829, 'Søpindsvin', 'Zee-egel', 'Oursin', 'Erizo de mar',
   'Søpindsvinet er et fascinerende dyr med et rundt, pigbeklædt ydre skelet. Det er et nyttigt havøkosystem-dyr, der lever af alger og organisk materiale. Dets "tænder" er et komplekst system kaldet Aristoteles lanterne.',
   'De zee-egel is een fascinerend dier met een rund, stekelachtig uitwendig skelet. Het is een nuttig mariene ecosysteemdier dat leeft van algen en organisch materiaal. Zijn "tanden" zijn een complex systeem genaamd de lantern van Aristoteles.',
   'L\'oursin est un animal fascinant avec un squelette externe rond couvert d\'épines. C\'est un animal utile pour l\'écosystème marin qui se nourrit d\'algues et de matières organiques. Ses "dents" sont un système complexe appelé lanterne d\'Aristote.',
   'El erizo de mar es un fascinante animal con un esqueleto externo redondo cubierto de espinas. Es un animal útil para el ecosistema marino que se alimenta de algas y materia orgánica. Sus "dientes" son un sistema complejo llamado linterna de Aristóteles.'],
  [830, 'Stikling', 'Stekelbaars', 'Épinoche', 'Espinoso',
   'Stiklingen er en lille sødvandsfisk, berømt for hannernes imponerende redebyggeri og forældreomsorg. Hannen bygger en rede af planter og vogter æggene alene, mens hunnen søger en ny partner.',
   'De stekelbaars is een kleine zoetwatervis, beroemd om het indrukwekkende nestbouw en ouderzorg van de mannetjes. Het mannetje bouwt een nest van planten en bewaakt de eieren alleen, terwijl het vrouwtje op zoek gaat naar een nieuwe partner.',
   'L\'épinoche est un petit poisson d\'eau douce, célèbre pour la construction de nids et les soins parentaux impressionnants des mâles. Le mâle construit un nid de plantes et garde seul les œufs, tandis que la femelle cherche un nouveau partenaire.',
   'El espinoso es un pequeño pez de agua dulce, famoso por la impresionante construcción de nidos y el cuidado parental de los machos. El macho construye un nido de plantas y cuida solo los huevos, mientras la hembra busca una nueva pareja.'],
  [831, 'Muling', 'Mul', 'Mulet', 'Mújol',
   'Multen er en bred gruppe af saltvandsfisk, der lever i kystvande verden over. Den er et vigtigt kommercielt fiskeri-mål og er tilpasset til at leve i miljøer med varierende saltholdighed, herunder i flodmundinger.',
   'De mul is een brede groep zoutwatervisssen die in kustwateren over de hele wereld leven. Het is een belangrijk commercieel visserijdoel en is aangepast om te leven in omgevingen met wisselende zoutgehaltes, waaronder riviermondingen.',
   'Le mulet est un large groupe de poissons de mer vivant dans les eaux côtières du monde entier. C\'est une cible importante de la pêche commerciale et il est adapté à vivre dans des environnements à salinité variable, y compris les estuaires.',
   'El mújol es un amplio grupo de peces marinos que viven en aguas costeras de todo el mundo. Es un objetivo importante de la pesca comercial y está adaptado a vivir en entornos con salinidad variable, incluidos los estuarios.'],
  [832, 'Sardin', 'Sardine', 'Sardine', 'Sardina',
   'Sardinen lever i store stimer i det Atlantiske og Middelhavsfarvan. De er et vigtigt led i havets fødekæde og er energirig mad for mange rovfisk, havpattedyr og havfugle. De er vigtige kommercielt.',
   'De sardine leeft in grote scholen in de Atlantische Oceaan en de Middellandse Zee. Ze zijn een belangrijke schakel in de voedselketen van de zee en zijn energierijk voedsel voor veel roofvissen, zeezoogdieren en zeevogels. Ze zijn commercieel belangrijk.',
   'La sardine vit en grandes écoles dans l\'Atlantique et la Méditerranée. Ce sont un maillon important de la chaîne alimentaire marine et une nourriture riche en énergie pour de nombreux poissons prédateurs, mammifères marins et oiseaux de mer. Elles sont importantes commercialement.',
   'La sardina vive en grandes bancos en el Atlántico y el Mediterráneo. Son un eslabón importante en la cadena alimentaria marina y un alimento rico en energía para muchos peces depredadores, mamíferos marinos y aves marinas. Son importantes comercialmente.'],
  [833, 'Søanemone', 'Zeeanemoon', 'Anémone de mer', 'Anémona de mar',
   'Søanemoner ligner blomster, men er faktisk rovdyr. De bruger deres gifttige tentakler til at paralysere og fange fisk og krebsdyr. Klovnefisk lever i symbiose med søanemoner og er immune over for deres gift.',
   'Zeeanemonen lijken op bloemen, maar zijn eigenlijk roofdieren. Ze gebruiken hun giftige tentakels om vissen en schaaldieren te verlammen en te vangen. Clownvissen leven in symbiose met zeeanemonen en zijn immuun voor hun gif.',
   'Les anémones de mer ressemblent à des fleurs, mais sont en réalité des prédateurs. Elles utilisent leurs tentacules venimeux pour paralyser et capturer des poissons et des crustacés. Les poissons clowns vivent en symbiose avec les anémones de mer et sont immunisés contre leur venin.',
   'Las anémonas de mar parecen flores, pero en realidad son depredadores. Usan sus tentáculos venenosos para paralizar y capturar peces y crustáceos. Los peces payaso viven en simbiosis con las anémonas de mar y son inmunes a su veneno.'],
  [834, 'Klovnefisk', 'Clownvis', 'Poisson clown', 'Pez payaso',
   'Klovnefisken er berømt fra animationsfilmen "Finding Nemo". Den lever i symbiose med søanemoner og er en af de eneste fisk, der er immune over for søanemoners gift. Den kan skifte køn i løbet af sit liv.',
   'De clownvis is beroemd geworden door de animatiefilm "Finding Nemo". Het leeft in symbiose met zeeanemonen en is een van de weinige vissen die immuun zijn voor het gif van zeeanemonen. Het kan van geslacht veranderen tijdens zijn leven.',
   'Le poisson clown est célèbre grâce au film d\'animation "Finding Nemo". Il vit en symbiose avec les anémones de mer et est l\'un des rares poissons immunisés contre le venin des anémones de mer. Il peut changer de sexe au cours de sa vie.',
   'El pez payaso se hizo famoso por la película de animación "Finding Nemo". Vive en simbiosis con las anémonas de mar y es uno de los pocos peces inmunes al veneno de las anémonas. Puede cambiar de sexo durante su vida.'],
  [835, 'Havlampret', 'Zeeprik', 'Lamproie marine', 'Lamprea marina',
   'Havlampretten er en primitiv, ålformet fisk uden kæbe. Den er en parasit, der fæstner sig til andre fisk med sin sugekopmund og lever af deres blod og kroppsvæsker. Den er et levende fossil.',
   'De zeeprik is een primitieve, aalvormige vis zonder kaak. Het is een parasiet die zich hecht aan andere vissen met zijn zuigbek en leeft van hun bloed en lichaamsvloeistoffen. Het is een levend fossiel.',
   'La lamproie marine est un poisson primitif en forme d\'anguille sans mâchoire. C\'est un parasite qui s\'attache aux autres poissons avec sa bouche en ventouse et vit de leur sang et de leurs fluides corporels. C\'est un fossile vivant.',
   'La lamprea marina es un pez primitivo en forma de anguila sin mandíbula. Es un parásito que se adhiere a otros peces con su boca en ventosa y vive de su sangre y fluidos corporales. Es un fósil viviente.'],
  [836, 'Svæv', 'Zwemkrab', 'Crabe nageur', 'Cangrejo nadador',
   'Svømmekrabben er en aktiv jæger, der er tilpasset til at svømme ved hjælp af sine flade bagben. Den er en vigtig del af kystøkosystemet og er en populær spise-krabke i mange kulturer.',
   'De zwemkrab is een actieve jager die is aangepast om te zwemmen met zijn platte achterpoten. Het is een belangrijk onderdeel van het kustecosysteem en is een populaire eetbare krab in veel culturen.',
   'Le crabe nageur est un chasseur actif adapté pour nager avec ses pattes postérieures aplaties. Il est une partie importante de l\'écosystème côtier et est un crabe comestible populaire dans de nombreuses cultures.',
   'El cangrejo nadador es un cazador activo adaptado para nadar con sus patas traseras aplanadas. Es una parte importante del ecosistema costero y es un cangrejo comestible popular en muchas culturas.'],
  [837, 'Torsk', 'Kabeljauw', 'Cabillaud', 'Bacalao',
   'Torsken er en af de vigtigste kommercielle fisk i verden og har haft stor betydning for europæisk og nordamerikansk historia. Den har en karakteristisk skæg under hagen og lever i kolde nordatlantiske farvande.',
   'De kabeljauw is een van de belangrijkste commerciële vissen ter wereld en heeft een grote betekenis gehad voor de Europese en Noord-Amerikaanse geschiedenis. Het heeft een karakteristische baard onder de kin en leeft in koude Noord-Atlantische wateren.',
   'La morue est l\'un des poissons commerciaux les plus importants du monde et a eu une grande signification pour l\'histoire européenne et nord-américaine. Elle a une barbe caractéristique sous le menton et vit dans les eaux froides de l\'Atlantique Nord.',
   'El bacalao es uno de los peces comerciales más importantes del mundo y ha tenido una gran importancia para la historia europea y norteamericana. Tiene una característica barba bajo la barbilla y vive en las frías aguas del Atlántico Norte.'],
  [838, 'Søstjerne', 'Zeester', 'Étoile de mer', 'Estrella de mar',
   'Søstjernen er et fascinerende pignehudsdyr med fem arme (eller flere). Den har en unik evne til at genskabe tabte arme. Den fordøjer sit bytte delvist udenfor kroppen ved at krampe sin mave ud.',
   'De zeester is een fascinerend stekelhuidig dier met vijf (of meer) armen. Het heeft een uniek vermogen om verloren armen te regenereren. Het verteert zijn prooi gedeeltelijk buiten het lichaam door zijn maag naar buiten te pompen.',
   'L\'étoile de mer est un animal échinoderme fascinant à cinq bras (ou plus). Elle a la capacité unique de régénérer les bras perdus. Elle digère partiellement ses proies en dehors du corps en extrudant son estomac.',
   'La estrella de mar es un fascinante equinodermo con cinco (o más) brazos. Tiene la capacidad única de regenerar brazos perdidos. Digiere parcialmente su presa fuera del cuerpo extrudiendo su estómago.'],
  [839, 'Havsnegl', 'Zeenaaktslak', 'Nudibranche', 'Nudibranquio',
   'Nøgensneglene er en gruppe havsnegles mangfoldige og farverige farvepragt. De bruger disse farver til at advare rovdyr om, at de er giftige. De mister deres skal tidligt i udviklingen.',
   'Naaktslakken zijn een groep van diverse en kleurrijke zeenaaktslakken. Ze gebruiken deze kleuren om roofdieren te waarschuwen dat ze giftig zijn. Ze verliezen vroeg in de ontwikkeling hun schelp.',
   'Les nudibranches sont un groupe de limaces de mer diverses et colorées. Ils utilisent ces couleurs pour avertir les prédateurs qu\'ils sont toxiques. Ils perdent leur coquille tôt dans leur développement.',
   'Los nudibranquios son un grupo de babosas marinas diversas y coloridas. Usan estos colores para advertir a los depredadores que son tóxicos. Pierden su concha temprano en el desarrollo.'],
  [840, 'Havsval', 'Zeekomkommer', 'Concombre de mer', 'Pepino de mar',
   'Havsvalerne er en gruppe pignehudsdyr, der lever på havbunden og spiser organisk materiale fra sedimentet. Når de er truede, kaster de deres indre organer ud som et forsvarsmiddel og kan gro nye.',
   'Zeekomkommers zijn een groep stekelhuidigen die op de zeebodem leven en organisch materiaal uit het sediment eten. Wanneer ze worden bedreigd, werpen ze hun inwendige organen uit als verdedigingsmiddel en kunnen nieuwe laten groeien.',
   'Les concombres de mer sont un groupe d\'échinodermes vivant sur les fonds marins et se nourrissant de matières organiques dans les sédiments. Lorsqu\'ils sont menacés, ils expulsent leurs organes internes comme mécanisme de défense et peuvent en faire pousser de nouveaux.',
   'Los pepinos de mar son un grupo de equinodermos que viven en el fondo del mar y comen materia orgánica de los sedimentos. Cuando son amenazados, expulsan sus órganos internos como mecanismo de defensa y pueden hacer crecer nuevos.'],
  [841, 'Havbars', 'Wolfsbaars', 'Loup de mer', 'Lobo de mar',
   'Havulven er en stor, rovagtig fisk med kraftige kæber fuld af skarpe tænder. Den lever i det kolde nordatlantiske hav og er tilpasset til at knuse hårde skaller fra byttedyr som krabber og muslinger.',
   'De wolfsbaars is een grote, roofzuchtige vis met krachtige kaken vol scherpe tanden. Het leeft in de koude Noordatlantische Oceaan en is aangepast om harde schelpen van prooidieren zoals krabben en mosselen te verpletteren.',
   'Le loup de mer est un grand poisson prédateur avec de puissantes mâchoires pleines de dents acérées. Il vit dans le froid Atlantique Nord et est adapté pour broyer les coquilles dures des proies comme les crabes et les moules.',
   'El lobo de mar es un gran pez depredador con poderosas mandíbulas llenas de dientes afilados. Vive en el frío Atlántico Norte y está adaptado para triturar las duras conchas de presas como cangrejos y mejillones.'],
  [842, 'Søhest (pygmæ)', 'Pygmee-zeepaard', 'Hippocampe pygmée', 'Caballito de mar pigmeo',
   'Det pygmæiske søheste er et af verdens mindste fisk og kan være kun 1,5 cm lang. Det er en mester i kamouflage og er næsten umulig at se mod sin koralbaggrund. Det er sent opdaget af videnskaben.',
   'Het pygmee-zeepaard is een van de kleinste vissen ter wereld en kan slechts 1,5 cm lang zijn. Het is een meester in camouflage en is bijna onmogelijk te zien tegen zijn koraalachtergrond. Het is laat ontdekt door de wetenschap.',
   'L\'hippocampe pygmée est l\'un des plus petits poissons du monde et peut mesurer seulement 1,5 cm de longueur. C\'est un maître du camouflage et il est presque impossible à voir contre son fond de corail. Il a été découvert tardivement par la science.',
   'El caballito de mar pigmeo es uno de los peces más pequeños del mundo y puede medir solo 1,5 cm de longitud. Es un maestro del camuflaje y es casi imposible de ver contra su fondo de coral. Fue descubierto tardíamente por la ciencia.'],
  [843, 'Søslange', 'Zeeslang', 'Serpent de mer', 'Serpiente marina',
   'Havsslangerne er en gruppe gifttige slanger, der er fuldt tilpasset til havlivet. De har en flad hale til at svømme og kan opholde sig under vand i timer. De meeste arter er fredeligt og bider sjældent mennesker.',
   'Zeeslangen zijn een groep giftige slangen die volledig zijn aangepast aan het mariene leven. Ze hebben een platte staart om te zwemmen en kunnen uren onder water verblijven. De meeste soorten zijn vredelievend en bijten zelden mensen.',
   'Les serpents de mer sont un groupe de serpents venimeux entièrement adaptés à la vie marine. Ils ont une queue aplatie pour nager et peuvent rester sous l\'eau pendant des heures. La plupart des espèces sont pacifiques et mordent rarement les humains.',
   'Las serpientes marinas son un grupo de serpientes venenosas completamente adaptadas a la vida marina. Tienen una cola aplanada para nadar y pueden permanecer bajo el agua durante horas. La mayoría de las especies son pacíficas y raramente muerden a humanos.'],
  [844, 'Mandarinfisk', 'Mandarijnvis', 'Poisson mandarin', 'Pez mandarín',
   'Mandarinfisken er en af de smukkeste fisk i verden med sit lysende blå og orange mønster. Den er hjemmehørende i det vestlige Stillehav og lever i lavt koralrev-vand. Den er aktiv om natten.',
   'De mandarijnvis is een van de mooiste vissen ter wereld met zijn helderblauw en oranje patroon. Het is inheems in de westelijke Stille Oceaan en leeft in ondiep koralrifwater. Het is \'s nachts actief.',
   'Le poisson mandarin est l\'un des plus beaux poissons du monde avec son motif bleu vif et orange. Il est originaire du Pacifique occidental et vit dans les eaux peu profondes des récifs coralliens. Il est actif la nuit.',
   'El pez mandarín es uno de los peces más hermosos del mundo con su brillante patrón azul y naranja. Es originario del Pacífico occidental y vive en aguas poco profundas de arrecifes de coral. Es activo por la noche.'],
];

let id = 1709;
const langs = ['da','nl','fr','es'];

process.stdout.write(`--\n-- Daten für Tabelle \`animaltext\` (da/nl/fr/es), Biome 700+800\n--\n`);
process.stdout.write(`INSERT INTO \`animaltext\` (\`id\`, \`animalId\`, \`languageCode\`, \`animalName\`, \`animalDescription\`) VALUES\n`);

const rows = [];
for (const a of animals) {
  const [animalId, ...rest] = a;
  for (let i = 0; i < 4; i++) {
    const lang = langs[i];
    const name = rest[i];
    const desc = rest[4 + i];
    rows.push(`(${id++}, ${animalId}, '${lang}', '${q(name)}', '${q(desc)}')`);
  }
}
process.stdout.write(rows.join(',\n') + ';\n');
process.stderr.write(`Generated ${rows.length} rows, IDs 1709–${id - 1}\n`);
